/**
 * Helper class that stores a step's condition of form ID<NUM
 * Tracks which parameter is used and the upper bound - useful for S3 checking
 */
class ConditionInfo{
    public String identifier;  // parameter used (ID1 or ID2)
    public long threshold;       // the NUM value - upper bound

    /**Constructor */
    public ConditionInfo(String id, long thresh) {
        this.identifier = id;
        this.threshold = thresh;
    }
}

/**
 * Stores a linear Arithmetic expression
 * Expressions are positive linear so can just store coefficients for num values
 * And the idCounts for each id
 * Evaluates expression in O(1)
 */
class ArithExpression {
    public long numSum; // sum of all individual constant terms
    public long id1Count; // coefficient of ID1
    public long id2Count; // coefficient of ID2

    /**Constructor */
    public ArithExpression(){
        this.numSum = 0;
        this.id1Count = 0;
        this.id2Count = 0;
    }

    //eval the value of this arithExpression with givens values of ID1,ID2
    public long eval(long ID1, long ID2){
        return numSum + (ID1 * id1Count) + (ID2 * id2Count);
    }

    //merge two nested ArithExpressions - i.e. x+(1+y) into a single expression
    public void merge(ArithExpression other){
        this.numSum += other.numSum;
        this.id1Count += other.id1Count;
        this.id2Count += other.id2Count;
    }

    /**
     * Verifies S3 rule for simplicity
     * When x<d is false - expression must be non-neg when cond is false
     * expr is smallest at x=d as x>=d. Set other ID to 0 and check non-neg
     */
    public boolean checkS3(boolean condUsesID1, long condThreshold){
        long result, ID1, ID2;

        if(condUsesID1){
            ID1 = condThreshold;
            ID2 = 0;
        }else{
            ID1 = 0;
            ID2 = condThreshold;
        }

        result = eval(ID1, ID2);
        return (result >= 0);
    }
}

/**
 * Represents the state of robot at a specific time during execution
 * Stores names, coords and wether robot has halted
 */
class State {
    String stepName;
    long x, y;
    boolean halted;

    /**Constructor */
    public State(String stepName, long x, long y) {
        this.stepName = stepName;
        this.x = x;
        this.y = y;
        this.halted = false;
    }

    //checks if two states are equal - automatically yes if both halted
    //used by Floyd's Cycle Detection Algorithm
    public boolean equals(State other) {
        if (this.halted && other.halted) return true;
        return this.stepName.equals(other.stepName) && this.x == other.x && this.y == other.y && this.halted == other.halted;
    }
}

